test("access_denied_is_not_absence", [&] {
    auto fixture = parent / "denied-metadata";
    fs::create_directory(fixture); makePrivate(fixture);
    std::ofstream(fixture / "child") << "safe";
    auto cleanup = hold(CreateFileW((fixture / "child").c_str(), READ_CONTROL | WRITE_DAC,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr));
    auto apply = [&](bool denied) {
        PSECURITY_DESCRIPTOR raw = nullptr;
        auto sddl = std::string("D:P") + (denied ? "(D;;0x80;;;" + user() + ")" : "") + "(A;;FA;;;" + user() + ")";
        require(ConvertStringSecurityDescriptorToSecurityDescriptorA(sddl.c_str(), SDDL_REVISION_1, &raw, nullptr), "SETUP denied-metadata DACL");
        auto sd = std::unique_ptr<void, decltype(&LocalFree)>(raw, &LocalFree);
        BOOL present, defaulted; PACL acl = nullptr;
        require(GetSecurityDescriptorDacl(raw, &present, &acl, &defaulted) && present && acl, "SETUP denied-metadata DACL decode");
        require(SetSecurityInfo(cleanup.get(), SE_FILE_OBJECT, DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION,
            nullptr, nullptr, acl, nullptr) == ERROR_SUCCESS, "SETUP denied-metadata DACL apply");
    };
    auto root = RootDirectory::open(utf8(fixture));
    apply(true);
    bool rejected = false;
    try { root->probeRegularFile("child"); }
    catch (const IOException& e) { rejected = std::string(e.what()).find("NTSTATUS=3221225506") != std::string::npos; }
    apply(false); root.reset(); cleanup.reset(); fs::remove_all(fixture);
    require(rejected, "access-denied metadata reported absent");
});
